.sc-tw :root{
            --basalt: oklch(12% 0.02 260);
            --amber: oklch(65% 0.15 45);
            --storm: oklch(25% 0.01 260);
        }.sc-tw{
            background-color: var(--basalt);
            color: #fff;
            margin: 0;
            font-family: 'Manrope', sans-serif;
            overflow-x: hidden;
        }.sc-tw .tectonic-section{
            position: sticky;
            top: 0;
            height: 100vh;
            width: 100%;
