            display: flex;
            align-items: center;
            background: var(--basalt);
            border-top: 1px solid rgba(255, 255, 255, 0.05);
        }.sc-tw .blade-mask{
            clip-path: polygon(0 0, 100% 0, 100% 85%, 25% 100%, 0 90%);
        }.sc-tw .sharp-card{
            clip-path: polygon(0 0, 100% 5%, 95% 100%, 0% 95%);
            background: rgba(255, 255, 255, 0.02);
